// WebClient: preferred HTTP client for inter-service calls (async, non-blocking, retry, timeout)
package com.bank.account.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.util.retry.Retry;
import java.time.Duration;

@Service
@Slf4j
public class ExternalKycClient {

    private final WebClient webClient;

    public ExternalKycClient(@Value("${external.kyc-service-url}") String baseUrl,
                              @Value("${external.connect-timeout}") Duration connectTimeout,
                              @Value("${external.read-timeout}") Duration readTimeout) {
        this.webClient = WebClient.builder()
            .baseUrl(baseUrl)
            .build();
    }

    public String getKycStatus(String customerId) {
        log.info("Calling KYC service for {}", customerId);
        return webClient.get()
            .uri("/api/v1/kyc/{customerId}", customerId)
            .retrieve()
            .bodyToMono(String.class)
            .timeout(Duration.ofSeconds(5))
            .retryWhen(Retry.backoff(3, Duration.ofSeconds(1)))
            .block();  // blocking call — in reactive app use .subscribe()
    }
}
