package com.bank.account.service;

import com.bank.account.dto.AccountResponse;
import com.bank.account.repository.AccountRepository;
import com.bank.account.security.JwtTokenProvider;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountService {

    private final AccountRepository accountRepo;
    private final JwtTokenProvider jwtProvider;

    public String login(String email) {
        var account = accountRepo.findByEmail(email)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + email));
        return jwtProvider.generateToken(email, account.getRole());
    }

    public AccountResponse getAccount(String accountId) {
        return accountRepo.findById(accountId)
            .map(AccountResponse::from)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + accountId));
    }

    // Method-level security: only ADMIN role can access
    @PreAuthorize("hasRole('ADMIN')")
    public List<AccountResponse> getAllAccounts() {
        log.info("Admin accessing all accounts");
        return accountRepo.findAll().stream().map(AccountResponse::from).toList();
    }
}
