package com.bank.account.controller;

import com.bank.account.dto.*;
import com.bank.account.service.AccountService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v1")
@RequiredArgsConstructor
public class AccountController {

    private final AccountService accountService;

    // PUBLIC — no auth required (configured in SecurityConfig)
    @PostMapping("/auth/login")
    public Map<String, String> login(@RequestBody @Valid LoginRequest request) {
        String token = accountService.login(request.email());
        return Map.of("token", token, "type", "Bearer");
    }

    // AUTHENTICATED — any valid JWT
    @GetMapping("/accounts/{accountId}")
    public AccountResponse getAccount(@PathVariable String accountId) {
        return accountService.getAccount(accountId);
    }

    // ADMIN ONLY — @PreAuthorize("hasRole('ADMIN')") on service method
    @GetMapping("/admin/accounts")
    public List<AccountResponse> getAllAccounts() {
        return accountService.getAllAccounts();
    }
}
