package com.bank.account.controller;

import com.bank.account.security.JwtTokenProvider;
import com.bank.account.service.AccountService;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.bean.MockBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
@DisplayName("Account Controller — Security Tests")
class AccountControllerSecurityTest {

    @Autowired MockMvc mvc;
    @Autowired JwtTokenProvider jwtProvider;
    @MockBean AccountService accountService;

    @Test
    @DisplayName("should allow public access to /auth/login")
    void loginShouldBePublic() throws Exception {
        mvc.perform(post("/api/v1/auth/login")
                .contentType("application/json")
                .content("""
                    {"email":"rajesh@bank.com","password":"pass"}
                    """))
            .andExpect(status().isOk());
    }

    @Test
    @DisplayName("should return 401 without JWT")
    void shouldReturn401WithoutToken() throws Exception {
        mvc.perform(get("/api/v1/accounts/SAV2001"))
            .andExpect(status().isUnauthorized());
    }

    @Test
    @DisplayName("should allow access with valid JWT")
    void shouldAllowWithValidJwt() throws Exception {
        String token = jwtProvider.generateToken("rajesh@bank.com", "USER");

        mvc.perform(get("/api/v1/accounts/SAV2001")
                .header("Authorization", "Bearer " + token))
            .andExpect(status().isOk());
    }

    @Test
    @DisplayName("should deny USER access to admin endpoint")
    void shouldDenyUserFromAdminEndpoint() throws Exception {
        String token = jwtProvider.generateToken("rajesh@bank.com", "USER");

        mvc.perform(get("/api/v1/admin/accounts")
                .header("Authorization", "Bearer " + token))
            .andExpect(status().isForbidden());
    }

    @Test
    @DisplayName("should allow ADMIN access to admin endpoint")
    void shouldAllowAdminAccess() throws Exception {
        String token = jwtProvider.generateToken("admin@bank.com", "ADMIN");

        mvc.perform(get("/api/v1/admin/accounts")
                .header("Authorization", "Bearer " + token))
            .andExpect(status().isOk());
    }
}
